"""Generate the Liquid vocabulary from the Flutter fallback; no catalog or credentials."""
import json,re,unicodedata
from pathlib import Path
root=Path(__file__).resolve().parents[4]
rules=json.loads((root/'assets/rules/normalization_rules.json').read_text())
copy=(root/'lib/app/shopper_copy.dart').read_text()
labels={}
for name,key in [('Category','categories'),('Silhouette','silhouettes'),('Color','colors'),('Pattern','patterns')]:
    body=re.search(r'k'+name+r'Labels = \{(.*?)\};',copy,re.S).group(1)
    labels[key]=dict(re.findall(r"'([^']+)': '([^']+)'",body))
labels['brands']={'guess':'Guess','coach':'Coach','michael_kors':'Michael Kors','steve_madden':'Steve Madden','tommy_hilfiger':'Tommy Hilfiger','anne_klein':'Anne Klein','christian_dior':'Christian Dior','olaplex':'Olaplex','the_ordinary':'The Ordinary','summer_fridays':'Summer Fridays','laneige':'Laneige','rhode':'Rhode'}
def fold(s): return ''.join(c for c in unicodedata.normalize('NFD',s.lower()) if unicodedata.category(c)!='Mn')
parts=["{%- comment -%}Generated by build-facets.py from assets/rules/normalization_rules.json v1 and Flutter shopper copy. Metafield override > tags > type > title > vendor (brand only) > collections. No prices or stock inferred. Unknown facts stay empty. Remote Config overrides are not available to Liquid.{%- endcomment -%}","{%- liquid", "  assign vocabulary = ''", "  assign limit = 1", "  case kind"]
for key,entries in ((k,rules[k]) for k in labels):
    encoded='|'.join('::'.join([k,labels[key].get(k,k.replace('_',' ').capitalize()),'~'.join(dict.fromkeys([fold(k.replace('_',' '))]+[fold(v) for v in vs]))]) for k,vs in entries.items())
    parts += [f"    when '{key}'",f"      assign vocabulary = '{encoded}' | split: '|'" ]
    if key in ['colors','patterns']:parts += [f"      assign limit = {3 if key=='colors' else 2}"]
parts+= ["  endcase", "  assign override = ''", "  if kind == 'brands'", "    assign override = product.metafields.app.brand_override.value | default: product.metafields.custom.marca.value", "  elsif kind == 'categories'", "    assign override = product.metafields.app.category_override.value", "  endif", "-%}", "{%- capture sources -%}{{ override }}§{{ product.tags | join: '¦' }}§{{ product.type }}§{{ product.title }}§{% if kind == 'brands' %}{{ product.vendor }}{% endif %}§{% for c in product.collections %}{{ c.handle | replace: '-', ' ' }}{% unless forloop.last %}¦{% endunless %}{% endfor %}{%- endcapture -%}","{%- liquid", "  assign tiers = sources | split: '§'", "  assign chosen = ''", "  for tier in tiers", "    assign tier_index = forloop.index0", "    assign matches = ''", "    assign signals = tier | split: '¦'", "    for signal in signals", "      capture folded", "        render 'monetta-fold', text: signal", "      endcapture", "      assign folded = folded | strip", "      if tier_index == 4 and kind == 'brands'", "        if folded == 'monetta' or folded == 'monetta wholesale' or folded == 'monetta wholesale llc'", "          continue", "        endif", "      endif", "      assign haystack = folded | prepend: ' ' | append: ' '", "      for entry in vocabulary", "        assign hit = false", "        assign bits = entry | split: '::'", "        assign aliases = bits[2] | split: '~'", "        for alias in aliases", "          assign needle = alias | prepend: ' ' | append: ' '", "          if haystack contains needle", "            assign hit = true", "            assign token = bits[0] | prepend: '|' | append: '|'", "            unless matches contains token", "              assign matches = matches | append: token", "            endunless", "            break", "          endif", "        endfor", "        if limit == 1 and hit", "          break", "        endif", "      endfor", "    endfor", "    if matches != blank", "      assign chosen = matches", "      break", "    elsif tier_index == 0 and override != blank", "      if output == 'key'", "        echo override | handleize | replace: '-', '_'", "      else", "        echo override", "      endif", "      break", "    endif", "  endfor", "  assign emitted = 0", "  if kind == 'categories'", "    assign priority = 'perfume,reloj,cosmetiquera,tarjetero,monedero,cartera,set,accesorio,bolsa' | split: ','", "    for key in priority", "      assign token = key | prepend: '|' | append: '|'", "      if chosen contains token", "        assign chosen = token", "        break", "      endif", "    endfor", "  endif", "  assign ordered_keys = chosen | split: '|' | uniq", "  for chosen_key in ordered_keys", "    if chosen_key == blank", "      continue", "    endif", "    for entry in vocabulary", "    assign bits = entry | split: '::'", "    assign token = bits[0] | prepend: '|' | append: '|'", "    if bits[0] == chosen_key", "      if emitted > 0", "        echo ', '", "      endif", "      if output == 'key'", "        echo bits[0]", "      else", "        echo bits[1]", "      endif", "      assign emitted = emitted | plus: 1", "      if emitted >= limit", "        break", "      endif", "    endif", "    endfor", "    if emitted >= limit", "      break", "    endif", "  endfor", "-%}"]
(root/'storefront-theme/snippets/monetta-facet.liquid').write_text('\n'.join(parts)+'\n')
accents={'áàäâã':'a','éèëê':'e','íìïî':'i','óòöôõ':'o','úùüû':'u','ñ':'n','ç':'c'}
filters='text | downcase'
for chars,replacement in accents.items():
    for ch in chars: filters+=f" | replace: '{ch}', '{replacement}'"
for ch in '-_.,:;/()[]+&!?–—': filters+=f" | replace: '{ch}', ' '"
filters+=" | replace: '  ', ' ' | replace: '  ', ' ' | strip"
(root/'storefront-theme/snippets/monetta-fold.liquid').write_text('{{- '+filters+' -}}\n')
